import {escapeHTML as e,validateContent,eventDates} from '/model.mjs';
import {eventFields,fighterFields,admissionFields,ticketFields,renderOffice,selectEvent,newEvent} from './events.js';
const app=document.querySelector('#app'),notice=document.querySelector('#notice');
let state,draft,tab='overview',dirty=false,busy=false,page='/',catalog=[],pageLinks=[],noticeTimer;
const paths={'/':'Home','/events/':'Events','/about/':'The fighter','/gallery/':'Gallery','/work-with-me/':'Partnerships','/become-a-sponsor/':'Sponsorship','/invite/':'Appearances','/contact/':'Contact','/faq/':'FAQs','/my-tickets/':'My tickets'};
const sections=[['overview','◉','Overview'],['event','◷','Next event'],['tickets','▤','Ticket prices'],['media','▧','Image library'],['gallery','▦','Gallery'],['copy','Aa','Page wording'],['history','↶','Publishing'],['ticketing','◇','Digital tickets']];
const logo='<div class="logo"><b>S<em>M</em></b><span>RINGSIDE STUDIO<small>WEBSITE MANAGEMENT</small></span></div>';
const label=s=>s.replace(/-/g,' ').replace(/\.(jpg|jpeg|png|webp)$/,'');
const date=s=>s?new Date(s).toLocaleString('en-GB'):'Original website';
function tell(message,error=false){notice.textContent=message;notice.className=error?'error':'';notice.style.display='block';clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>notice.style.display='none',8000);}
async function api(path,options={}){const r=await fetch(path,{...options,headers:{'Content-Type':'application/json',...options.headers},cache:'no-store'});let data;try{data=await r.json()}catch{throw Error('The dashboard service is unavailable. Check the Netlify deployment.');}if(!r.ok)throw Error(data.error||'Request failed.');return data;}
function value(path){return path.reduce((o,k)=>o[k],draft);}
function field(title,path,type='text',help='',choices){const val=value(path)??'';const attrs=`data-path="${e(JSON.stringify(path))}"`;return `<label class="field ${type==='textarea'?'full':''}"><span>${e(title)}</span>${choices?`<select ${attrs}>${choices.map(([v,l])=>`<option value="${e(v)}" ${v===val?'selected':''}>${e(l)}</option>`).join('')}</select>`:type==='textarea'?`<textarea ${attrs}>${e(val)}</textarea>`:`<input ${attrs} type="${type}" value="${e(val)}" ${type==='number'?'min="0" max="10000" step="0.01"':''}>`}${help?`<small>${e(help)}</small>`:''}</label>`;}
function heading(k,title,copy){return `<div class="heading"><span class="eyebrow">${k}</span><h1>${title}</h1><p>${copy}</p></div>`;}
function shell(){app.innerHTML=`<aside class="sidebar">${logo}<nav aria-label="Dashboard">${sections.map(([id,icon,name])=>`<button data-tab="${id}" aria-current="${tab===id?'page':'false'}"><span>${icon}</span>${name}</button>`).join('')}</nav><div class="bottom"><a href="/" target="_blank" rel="noopener">View live website ↗</a><button class="quiet" id="logout">Sign out</button></div></aside><div class="workspace"><header class="topbar"><span class="status" id="save-status">${dirty?'Unsaved changes':state.savedAt?'Draft saved '+date(state.savedAt):'Ready to edit'}</span><div class="actions"><button id="save">Save draft</button><button id="preview">Preview ↗</button><button class="primary" id="publish">Publish changes</button></div></header><main class="content" id="content"></main></div>`;render();}
function render(){document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-current',b.dataset.tab===tab?'page':'false'));const out=document.querySelector('#content');out.dataset.officeView='';
  if(tab==='overview'){let d;try{d=eventDates(draft.event)}catch{d={short:'Choose a date'}};out.innerHTML=heading('Your corner of the internet','Ready for the next round.','One place to keep every event detail, image and word up to date.')+`<div class="cards"><div class="card"><span class="eyebrow">Next event</span><strong>${e(d.short)}</strong><small>${e(draft.event.time)} UK time · ${e(draft.event.status)}</small></div><div class="card"><span class="eyebrow">Ticket experiences</span><strong>${draft.tickets.length} categories</strong><small>From £${Math.min(...draft.tickets.map(t=>t.price))} per person</small></div><div class="card"><span class="eyebrow">Last published</span><strong>${state.publishedAt?'Website updated':'Original website'}</strong><small>${date(state.publishedAt)}</small></div></div><div class="panel hero-card"><div><span class="eyebrow">Next in the spotlight</span><h2>${e(draft.event.city)}.<br>${e(draft.event.tagline)}</h2><p>${e(draft.event.venue)}<br>${e(draft.event.promoter)}</p><button data-tab="event" class="primary">Edit the next event →</button></div><img src="${e(draft.media['hero-painted-portrait.png'].url)}" alt=""></div><div class="section-grid"><div class="panel"><h2>Edit once. Update everywhere.</h2><p>The event date feeds the hero, scrolling banner, event cards, countdowns and ticket labels.</p><button data-tab="media">Manage images</button></div><div class="panel"><h2>Your changes, on your terms.</h2><p>Save a draft, preview it, then publish. The last ten published versions are available to restore.</p><button data-tab="history">Publication history</button></div></div>`;}
  if(tab==='event')out.innerHTML=heading('Event management','Set the next fight night.','Changes here update every event reference across the website when published.')+`<div class="panel"><h2>The headline</h2><p>Introduce the event and the people behind it.</p><div class="fields">${field('Event title',['event','title'])}${field('Featured fighter',['event','fighter'])}${field('Promoted by',['event','promoter'])}${field('City',['event','city'])}${field('Venue / full address',['event','venue'])}${field('Event tagline',['event','tagline'])}</div></div><div class="panel"><h2>Date & booking</h2><p>The countdown uses UK local time and adjusts automatically for British Summer Time.</p><div class="fields">${field('Event date',['event','date'],'date')}${field('Doors open (UK time)',['event','time'],'time')}${field('Event status',['event','status'],'text','Postponed, cancelled and sold-out events stop the countdown and disable booking links.',['draft','scheduled','postponed','cancelled','sold out','completed'].map(x=>[x,x]))}${field('Secure booking page',['event','bookingURL'],'url','Stripe is not connected yet. This remains the team’s external booking page.')}${field('Message after the countdown ends',['event','expiredMessage'],'textarea')}${field('Contact telephone',['contact','phone'],'tel')}</div></div>`;
  if(tab==='tickets')out.innerHTML=heading('Ticket experiences','Every seat. Your pricing.','Change display prices and descriptions. Until Stripe is connected, keep these in step with the external booking provider.')+draft.tickets.map((t,i)=>`<div class="panel"><div class="row-heading"><h2>${e(t.name)}</h2><button data-remove-ticket="${i}" class="quiet" ${draft.tickets.length===1?'disabled':''}>Remove category</button></div><div class="fields">${field('Ticket name',['tickets',i,'name'])}${field('Price in GBP',['tickets',i,'price'],'number')}${field('Short description',['tickets',i,'desc'],'textarea')}${field('What’s included',['tickets',i,'detail'],'textarea')}</div></div>`).join('')+'<p style="margin-top:24px"><button id="add-ticket">+ Add ticket category</button></p>';
  if(tab==='media')out.innerHTML=heading('Image library','Put the story in frame.','Replace any image, including the hero paintings, event poster and dark backgrounds. Set the focal point to control the crop.')+`<div class="media-grid">${Object.entries(draft.media).map(([key,m])=>`<article class="panel media-card"><img data-media-preview="${e(key)}" src="${e(m.url)}" style="object-position:${e(m.position)}" alt="${e(m.alt)}"><div class="fields"><strong class="name">${e(key.startsWith('b075')?'Event poster · Glasgow under the lights':label(key))}</strong><label class="field"><span>Upload replacement</span><input type="file" data-upload="${e(key)}" accept="image/jpeg,image/png,image/webp"><small>JPEG, PNG or WebP · up to 4 MB. Updates all uses of this image.</small></label>${field('Image address',['media',key,'url'],'url')}${field('Image description (alt text)',['media',key,'alt'])}<label class="field"><span>Horizontal focal point</span><input type="range" min="0" max="100" value="${parseInt(m.position)}" data-crop="${e(key)}" data-axis="0"></label><label class="field"><span>Vertical focal point</span><input type="range" min="0" max="100" value="${parseInt(m.position.split(' ')[1])}" data-crop="${e(key)}" data-axis="1"></label></div></article>`).join('')}</div>`;
  if(tab==='gallery')out.innerHTML=heading('Inside the ropes','A gallery that belongs together.','All photographs share a rounded 4:3 frame. The first three appear on the homepage; move them into your preferred order.')+draft.gallery.map((p,i)=>`<div class="panel gallery-row"><img src="${e(draft.media[p[0]].url)}" style="object-position:${e(draft.media[p[0]].position)}" alt=""><div class="fields">${field('Photograph',['gallery',i,0],'text','',Object.keys(draft.media).map(k=>[k,label(k)]))}${field('Caption',['gallery',i,1])}${field('Description for screen readers',['gallery',i,2])}${field('Category',['gallery',i,3],'text','',['Fight night','Training','Portraits'].map(x=>[x,x]))}</div><div class="actions"><button data-move="${i}" data-direction="-1" aria-label="Move photograph ${i+1} up" ${i===0?'disabled':''}>↑</button><button data-move="${i}" data-direction="1" aria-label="Move photograph ${i+1} down" ${i===draft.gallery.length-1?'disabled':''}>↓</button><button data-remove-photo="${i}" ${draft.gallery.length===1?'disabled':''}>Remove</button></div></div>`).join('')+'<button id="add-photo">+ Add photograph from library</button><p style="margin-top:16px">To add a new image, upload it here first: <input type="file" id="new-photo" accept="image/jpeg,image/png,image/webp"></p>';
  if(tab==='copy'){out.innerHTML=heading('Page wording','Make every word yours.','Select a page to edit its wording and links. Shared phrases update everywhere. Dates, tickets and gallery captions have their own sections.')+`<div class="tabs"><label for="page">Page</label><select id="page">${Object.entries(paths).map(([p,n])=>`<option value="${p}" ${p===page?'selected':''}>${n}</option>`).join('')}</select><button id="refresh-copy">Refresh preview</button></div><div class="copy-layout"><div id="copy-fields" class="copy-fields"><p>Loading page fields…</p></div><iframe title="Draft page preview" src="${e(page)}?preview=1"></iframe></div>`;}
  if(tab==='history')out.innerHTML=heading('Publishing','A little peace of mind.','Restore a previous publication into your draft, review it, then publish when you’re ready.')+`<div class="panel"><div class="row-heading"><h2>Publication history</h2><button id="export">Download backup</button></div><p>Last published: ${date(state.publishedAt)}. Changes are stored on Netlify and survive code deployments.</p>${state.history.length?state.history.map(h=>`<div class="history-row"><div><strong>${e(h.content.event.title)}</strong><small>${date(h.date)} · ${e(h.content.event.date)}</small></div><button data-restore="${e(h.id)}">Restore to draft</button></div>`).join(''):'<div class="empty">Your publication history will appear after the first publish.</div>'}</div>`;
  if(tab==='event')out.insertAdjacentHTML('beforeend',fighterFields(field)+eventFields(draft,field)+admissionFields(field));
  if(tab==='event')out.insertAdjacentHTML('beforeend','<div class="panel"><h2>Preview the customer email</h2><p>Review the confirmation or event-update message with example booking details. No email is sent.</p><div class="actions"><button data-email-preview="confirmation">Preview booking confirmation</button><button data-email-preview="update">Preview current event update</button></div><div id="email-preview"></div></div>');
  if(tab==='tickets')out.insertAdjacentHTML('beforeend',ticketFields(draft,field));
  if(tab==='ticketing')renderOffice(out,api);
  if(!state.workflowReady)out.insertAdjacentHTML('afterbegin','<div class="banner">The event database update has not been activated here. Content can be prepared, but connected event publishing and notifications need activation.</div>');
}
function mark(){dirty=true;document.querySelector('#save-status').textContent='Unsaved changes';}
function hydrate(s){state=s;draft=validateContent(s.draft);dirty=false;}
async function save(){validateContent(draft);hydrate(await api('/api/admin/content',{method:'POST',body:JSON.stringify({action:'save',revision:state.revision,content:draft})}));document.querySelector('#save-status').textContent='Draft saved '+date(state.savedAt);}
async function run(fn){if(busy)return;busy=true;document.querySelectorAll('.topbar button').forEach(b=>b.disabled=true);try{await fn()}catch(err){tell(err.message,true)}finally{busy=false;document.querySelectorAll('.topbar button').forEach(b=>b.disabled=false);}}
async function upload(file,key){if(!file)return;if(file.size>4000000)throw Error('Use an image smaller than 4 MB.');const result=await api('/api/media',{method:'POST',headers:{'Content-Type':file.type},body:file});if(!key){key='upload-'+crypto.randomUUID()+'.jpg';draft.media[key]={url:result.url,alt:'',position:'50% 50%'};draft.gallery.push([key,'New photograph','','Training']);}else draft.media[key].url=result.url;mark();render();tell('Image uploaded. Save and publish to update the website.');}
function copyFields(){const fields=document.querySelector('#copy-fields');if(!fields)return;const key=page.replace(/\/$/,'')||'/';draft.pages??={};draft.pages[key]??={title:'',description:''};fields.innerHTML=`<div class="panel"><h2 style="margin-bottom:20px">Search appearance</h2>${field('Page title',['pages',key,'title'])}${field('Search description',['pages',key,'description'],'textarea')}</div><div class="panel"><h2 style="margin-bottom:20px">Page wording</h2>${catalog.map(text=>{draft.text[text]??=text;return field(text,['text',text],text.length>80?'textarea':'text')}).join('')}</div><div class="panel"><h2 style="margin-bottom:20px">Links</h2>${pageLinks.map(({key,label})=>{draft.links[key]??=key;return field(label||key,['links',key],'text',key)}).join('')}</div>`;}
window.addEventListener('message',event=>{const frame=document.querySelector('iframe');if(event.origin!==location.origin||event.source!==frame?.contentWindow||event.data?.type!=='ringside-catalog')return;page=event.data.path==='/'?'/':event.data.path+'/';document.querySelector('#page').value=page;catalog=event.data.text;pageLinks=event.data.links;draft.pages??={};draft.pages[event.data.path]??={title:event.data.title,description:event.data.description};copyFields();});
app.addEventListener('input',event=>{const input=event.target;if(input.dataset.path){const path=JSON.parse(input.dataset.path),key=path.pop(),target=path.reduce((o,k)=>o[k],draft);target[key]=key==='enabled'?input.value==='true':input.type==='number'?Number(input.value):input.value;mark();}if(input.dataset.crop){const key=input.dataset.crop,parts=draft.media[key].position.split(' ');parts[Number(input.dataset.axis)]=input.value+'%';draft.media[key].position=parts.join(' ');draft.media[key].customCrop=true;input.closest('article').querySelector('img').style.objectPosition=parts.join(' ');mark();}});
app.addEventListener('submit',event=>{if(!event.target.dataset.requestId)return;event.preventDefault();const form=event.target;run(async()=>{await api('/api/admin/events',{method:'POST',body:JSON.stringify({id:form.dataset.requestId,...Object.fromEntries(new FormData(form))})});tell('Request progress saved. No payment or ticket was changed.');render();});});
app.addEventListener('change',event=>{if(event.target.dataset.upload)run(()=>upload(event.target.files[0],event.target.dataset.upload));if(event.target.id==='new-photo')run(()=>upload(event.target.files[0]));if(event.target.id==='page'){page=event.target.value;render();}});
app.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.tab){tab=b.dataset.tab;render();return;}
  run(async()=>{
    if(b.id==='save'){await save();tell('Draft saved. The public website is unchanged.');}
    if(b.id==='publish'){
      if(['cancelled','postponed'].includes(draft.event.status)&&!confirm(`Publish this event as ${draft.event.status.toUpperCase()}? Booking and admission close, the website displays the notice, and customer notifications are queued. Refunds and transfers are separate actions.`))return;
      if(!['cancelled','postponed','completed'].includes(draft.event.status)&&draft.event.fighterStatus==='withdrawn'&&!confirm(`Publish the fighter withdrawal notice for ${draft.event.fighter}? The event remains ${draft.event.status}; booking and admission follow the event status. Customer updates will be queued.`))return;
      await save();hydrate(await api('/api/admin/content',{method:'POST',body:JSON.stringify({action:'publish',revision:state.revision})}));render();tell('Published. Event details and notification requests are updated.');}
    if(b.id==='preview'){await save();window.open('/?preview=1','ringside-preview');tell('Preview opened with your saved draft.');}
    if(b.id==='refresh-copy'){await save();render();}
    if(b.id==='logout'){if(dirty&&!confirm('Sign out without saving your changes?'))return;await api('/api/session',{method:'DELETE'});location.reload();}
    if(b.id==='add-ticket'){draft.tickets.push({id:crypto.randomUUID(),name:'New ticket',price:0,capacity:100,enabled:false,desc:'',detail:''});mark();render();}
    if(b.id==='new-event'){if(dirty&&!confirm('Replace your unsaved event edits?'))return;newEvent(draft);mark();render();tell('New event draft created. Set its date, venue, prices and status before publishing.');}
    if(b.dataset.emailPreview){const data=await api('/api/admin/events',{method:'POST',body:JSON.stringify({action:'preview-email',kind:b.dataset.emailPreview,event:{...draft.event,contactPhone:draft.contact.phone}})}),target=document.querySelector('#email-preview');target.replaceChildren();target.append(Object.assign(document.createElement('h3'),{textContent:data.subject}));const frame=document.createElement('iframe');frame.setAttribute('sandbox','');frame.title='Example customer email';frame.style.cssText='width:100%;height:700px;border:0;margin-top:24px;background:white';frame.srcdoc=data.html;target.append(frame);}
    if(b.dataset.editEvent){if(dirty&&!confirm('Replace your unsaved event edits?'))return;selectEvent(b.dataset.editEvent,draft);tab='event';mark();render();}
    if(b.dataset.removeTicket!==undefined){draft.tickets.splice(Number(b.dataset.removeTicket),1);mark();render();}
    if(b.id==='add-photo'){draft.gallery.push([Object.keys(draft.media)[0],'New photograph','','Fight night']);mark();render();}
    if(b.dataset.removePhoto!==undefined){draft.gallery.splice(Number(b.dataset.removePhoto),1);mark();render();}
    if(b.dataset.move!==undefined){const i=Number(b.dataset.move),j=i+Number(b.dataset.direction);[draft.gallery[i],draft.gallery[j]]=[draft.gallery[j],draft.gallery[i]];mark();render();}
    if(b.dataset.restore){if(dirty&&!confirm('Replace your unsaved edits with this published version?'))return;hydrate(await api('/api/admin/content',{method:'POST',body:JSON.stringify({action:'restore',revision:state.revision,id:b.dataset.restore})}));render();tell('Restored to draft. Preview it before publishing.');}
    if(b.id==='export'){const blob=new Blob([JSON.stringify(draft,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ringside-content-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  });
});
addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
async function boot(){try{const status=await api('/api/session');if(status.authenticated){hydrate(await api('/api/admin/content'));shell();return;}
  if(status.individualAccounts){app.innerHTML=`<main class="panel login">${logo}<h1>Your website.<br>Your corner.</h1><p>Use your own staff email, password and authenticator to open Ringside Studio.</p>${status.configured?'<a class="button primary" href="/door/?next=admin">Sign in with my staff account →</a>':'<div class="banner">Individual staff accounts are awaiting activation. Ask the organiser to finish the Supabase connection.</div>'}<p>Only owners and editors can change the website. Door staff have access to assigned events in the scanner.</p><p><a href="/door/">Open Ringside Door →</a></p></main>`;return;}
  app.innerHTML=`<main class="panel login">${logo}<h1>Your website.<br>Your corner.</h1><p>Sign in to manage events, tickets, images and page content.</p>${!status.configured?'<div class="banner">Admin access is locked until the owner sets a password in Netlify.</div><details open><summary>One-time activation</summary><p>In this site’s Netlify project, open <b>Project configuration → Environment variables → Add a variable</b>. Name it <code>CMS_ADMIN_PASSWORD</code>, enter a private password of at least 20 characters, and make it available to Functions. Then deploy the site again. Keep the password out of GitHub and chat.</p></details>':''}<form id="login"><label class="field"><span>Admin password</span><input name="password" type="password" autocomplete="current-password" required minlength="20" ${!status.configured?'disabled':''}></label><button class="primary" ${!status.configured?'disabled':''}>Sign in →</button><p id="login-error" class="error-text" role="alert"></p></form><p style="margin-top:25px;font-size:12px"><a href="/">← Back to website</a></p></main>`;
  document.querySelector('#login').onsubmit=async event=>{event.preventDefault();const b=event.target.querySelector('button');b.disabled=true;try{await api('/api/session',{method:'POST',body:JSON.stringify({password:new FormData(event.target).get('password')})});event.target.reset();await boot()}catch(err){document.querySelector('#login-error').textContent=err.message}finally{b.disabled=false}};
}catch(err){app.innerHTML=`<main class="panel login">${logo}<h1>Service unavailable.</h1><p>${e(err.message)}</p><p>This dashboard requires the Netlify deployment with its server functions.</p><a href="/">Back to website</a></main>`;}}
boot();
